SELECT percentile_cont(0.95) within GROUP (ORDER BY f.value) AS percentile_value, f.los, f.deathtime, CAST(COUNT(DISTINCT CASE WHEN f.value > 1 THEN f.hadm_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT g.hadm_id), 0) AS critical_rate, CAST(COUNT(DISTINCT CASE WHEN g.value > 1 THEN g.hadm_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT f.hadm_id), 0) AS general_rate FROM f FULL JOIN g G ON f.hadm_id = g.hadm_id GROUP BY f.los, f.deathtime;